package main

import (
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type OrderRec struct {
	OrId    string
	OrStat  string
	OrQty   int64
	OrPrice decimal.Decimal
}

var WsEofFlag string = "N"
var WsTotal decimal.Decimal = decimal.New(0, 0)
var WsGrand decimal.Decimal = decimal.New(0, 0)
var WsNewCount int64 = 0
var WsShipCount int64 = 0
var WsCancelCount int64 = 0
var WsInvalid int64 = 0
var WsBadQty int64 = 0
var WsQtyEd string
var WsPriceEd string
var WsTotalEd string
var WsGrandEd string

var orderRec OrderRec
var orderLines []string
var orderIdx int

func isInputDone() bool {
	return WsEofFlag == "Y"
}

func padRight(s string, n int) string {
	if len(s) >= n {
		return s[:n]
	}
	return s + strings.Repeat(" ", n-len(s))
}

func parseOrderRec(line string) OrderRec {
	rec := padRight(line, 15)
	orId := rec[0:5]
	orStat := rec[5:6]
	orQtyStr := rec[6:9]
	orPriceStr := rec[9:15]

	var qty int64 = 0
	qs := strings.TrimSpace(orQtyStr)
	if qs != "" {
		var v int64
		fmt.Sscanf(qs, "%d", &v)
		qty = v
		// fallback for non-numeric? treat as 0
		// if Sscanf fails, try manual
		if qs != fmt.Sprintf("%0*d", len(qs), qty) {
			// try parse stripped leading zeros
			// already
		}
	}
	// more robust: parse digits only
	if qs != "" {
		var n int64 = 0
		for _, ch := range qs {
			if ch >= '0' && ch <= '9' {
				n = n*10 + int64(ch-'0')
			}
		}
		// if qs was numeric, n is correct; if not, keep 0
		// Determine if qs is all digits
		allDigits := true
		for _, ch := range qs {
			if ch < '0' || ch > '9' {
				allDigits = false
				break
			}
		}
		if allDigits {
			qty = n
		}
	}

	var price decimal.Decimal = decimal.Zero
	ps := strings.TrimSpace(orPriceStr)
	if ps != "" {
		// price is digits only, implied V99
		// ps may contain non-digits? assume digits
		var n int64 = 0
		for _, ch := range ps {
			if ch >= '0' && ch <= '9' {
				n = n*10 + int64(ch-'0')
			}
		}
		price = decimal.New(n, -2)
	}

	return OrderRec{
		OrId:    orId,
		OrStat:  orStat,
		OrQty:   qty,
		OrPrice: price,
	}
}

func formatIntPadded(val int64, digits int) string {
	// high-order digits dropped
	if val < 0 {
		val = -val
	}
	s := fmt.Sprintf("%0*d", digits, val)
	if len(s) > digits {
		s = s[len(s)-digits:]
	}
	return s
}

func formatEdited(value decimal.Decimal, pic string) string {
	// pic like "ZZ9", "Z,ZZ9.99", "ZZ,ZZZ,ZZ9.99", "Z,ZZZ,ZZZ,ZZ9.99"
	// Determine decimal places
	dotIdx := strings.Index(pic, ".")
	var intPic string
	var decLen int
	if dotIdx >= 0 {
		intPic = pic[:dotIdx]
		decPart := pic[dotIdx+1:]
		decLen = len(decPart) // number of 9s
	} else {
		intPic = pic
		decLen = 0
	}
	// count integer digit placeholders
	intDigits := 0
	for _, ch := range intPic {
		if ch == 'Z' || ch == '9' {
			intDigits++
		}
	}
	// absolute value
	absVal := value.Abs()

	// Build string representation with exactly decLen fractional digits, truncated
	// We need Truncate to decLen for move semantics (no rounding)
	truncated := absVal.Truncate(int32(decLen))
	// Now get integer and fractional strings via StringFixed with truncation already done
	// StringFixed would round, but since we truncated, rounding won't change.
	var intStr, fracStr string
	if decLen > 0 {
		// Use StringFixed to get padded fractional part
		// truncated already has at most decLen scale, StringFixed will pad zeros
		s := truncated.StringFixed(int32(decLen))
		parts := strings.SplitN(s, ".", 2)
		intStr = parts[0]
		if len(parts) > 1 {
			fracStr = parts[1]
		} else {
			fracStr = strings.Repeat("0", decLen)
		}
		// Handle negative zero? strip sign already via Abs
		if intStr == "" {
			intStr = "0"
		}
		// Remove sign if present (should not)
		if strings.HasPrefix(intStr, "-") {
			intStr = intStr[1:]
		}
	} else {
		// no decimal part, integer truncated to 0 decimals
		s := truncated.StringFixed(0)
		// s may contain "."
		if idx := strings.Index(s, "."); idx >= 0 {
			s = s[:idx]
		}
		if strings.HasPrefix(s, "-") {
			s = s[1:]
		}
		if s == "" {
			s = "0"
		}
		intStr = s
		fracStr = ""
	}

	// Drop high-order digits if needed
	if len(intStr) > intDigits {
		intStr = intStr[len(intStr)-intDigits:]
	}
	// pad left zeros to intDigits
	if len(intStr) < intDigits {
		intStr = strings.Repeat("0", intDigits-len(intStr)) + intStr
	}
	digitsRunes := []rune(intStr)
	digitIdx := 0
	suppressed := true
	var intBuilt strings.Builder
	for _, ch := range intPic {
		switch ch {
		case ',':
			if suppressed {
				intBuilt.WriteRune(' ')
			} else {
				intBuilt.WriteRune(',')
			}
		case 'Z', '9':
			d := digitsRunes[digitIdx]
			digitIdx++
			if suppressed {
				if d != '0' {
					suppressed = false
				}
			}
			if suppressed && ch == 'Z' && d == '0' {
				intBuilt.WriteRune(' ')
			} else {
				// if we are still suppressed and this is '9' with d==0, we output '0' and keep suppressed? For comma logic, once we output a '9' zero, should comma after be considered not suppressed? Actually after printing '0' via 9, we are no longer considered suppressed for subsequent commas? But there are no commas after last 9. For pattern where 9 in middle, future commas should be visible. The suppression ends after we output the 9 zero? In COBOL, if integer is zero, commas remain spaces. So even after printing 0, commas before were spaces. But commas after? There are none. For safety, if we printed a '9', suppression ends for future commas? However for zero value, we don't want commas. Let's define: if ch=='9', after writing, set suppressed=false if we consider zero as not suppressing commas after? But there are no commas after last digit. To keep commas spaces for zero, we should NOT clear suppressed when the value is entirely zero. Simpler: keep suppressed true if all remaining digits are zero and we are still in leading zero region. Our current logic clears suppressed only on non-zero digit, which keeps commas as spaces for zero case. That's correct.
				// For non-zero case, suppressed already false due to prior non-zero, so we output digit.
				intBuilt.WriteRune(d)
				// Do not change suppressed here beyond non-zero check
			}
			// If ch == '9' and d=='0' and suppressed still true (all zeros), we have printed '0' but suppressed remains true, which keeps any preceding commas spaces (already done) and is fine. Future commas (should not exist) would stay spaces.
		}
	}
	result := intBuilt.String()
	if decLen > 0 {
		result = result + "." + fracStr
	}
	// Ensure length equals pic length (should already)
	// If result shorter due to something, pad? but not needed
	return result
}

func MAIN_PARA() {
	OPEN_INPUT()
	READ_PARA()
	for !isInputDone() {
		PROCESS_PARA()
	}
	CLOSE_INPUT()
	SUMMARY_PARA()
}

func OPEN_INPUT() {
	data, err := os.ReadFile("input.dat")
	if err != nil {
		// if file not found, treat as empty
		orderLines = []string{}
		orderIdx = 0
		return
	}
	// Split into lines on \n, handling \r
	text := string(data)
	// Use split after normalizing \r\n -> \n
	text = strings.ReplaceAll(text, "\r\n", "\n")
	text = strings.ReplaceAll(text, "\r", "\n")
	if text == "" {
		orderLines = []string{}
	} else {
		parts := strings.Split(text, "\n")
		// COBOL LINE SEQUENTIAL: each line is a record. If file ends with newline, Split will produce trailing empty element which should not be considered as extra record? In COBOL, a final newline does not create extra record. So drop trailing empty if original text ends with \n
		if strings.HasSuffix(text, "\n") && len(parts) > 0 && parts[len(parts)-1] == "" {
			parts = parts[:len(parts)-1]
		}
		orderLines = parts
	}
	orderIdx = 0
}

func CLOSE_INPUT() {
	// no-op
}

func READ_PARA() {
	if orderIdx >= len(orderLines) {
		WsEofFlag = "Y"
		return
	}
	line := orderLines[orderIdx]
	orderIdx++
	orderRec = parseOrderRec(line)
}

func PROCESS_PARA() {
	WsTotal = decimal.Zero

	if orderRec.OrQty == 0 {
		WsBadQty++
		// DISPLAY OR-ID " BAD QTY"
		fmt.Printf("%s BAD QTY\n", orderRec.OrId)
	} else if orderRec.OrStat == "N" {
		raw := decimal.NewFromInt(orderRec.OrQty).Mul(orderRec.OrPrice)
		WsTotal = raw.Truncate(2)
		WsNewCount++
		SHOW_PARA()
	} else if orderRec.OrStat == "S" {
		raw := decimal.NewFromInt(orderRec.OrQty).Mul(orderRec.OrPrice).Mul(decimal.NewFromFloat(1.05))
		// Use exact decimal for 1.05 to avoid float
		// Recompute with exact to be safe
		rawExact := decimal.NewFromInt(orderRec.OrQty).Mul(orderRec.OrPrice).Mul(decimal.New(105, -2))
		WsTotal = rawExact.Round(2)
		_ = raw
		WsShipCount++
		SHOW_PARA()
	} else if orderRec.OrStat == "C" {
		WsCancelCount++
		SHOW_PARA()
	} else {
		WsInvalid++
		fmt.Printf("%s BAD STATUS %s\n", orderRec.OrId, orderRec.OrStat)
	}
	WsGrand = WsGrand.Add(WsTotal)
	READ_PARA()
}

func SHOW_PARA() {
	WsQtyEd = formatEdited(decimal.NewFromInt(orderRec.OrQty), "ZZ9")
	WsPriceEd = formatEdited(orderRec.OrPrice, "Z,ZZ9.99")
	WsTotalEd = formatEdited(WsTotal, "ZZ,ZZZ,ZZ9.99")
	// DISPLAY OR-ID " " OR-STAT " " WS-QTY-ED " " WS-PRICE-ED " " WS-TOTAL-ED.
	fmt.Printf("%s %s %s %s %s\n", orderRec.OrId, orderRec.OrStat, WsQtyEd, WsPriceEd, WsTotalEd)
}

func SUMMARY_PARA() {
	WsGrandEd = formatEdited(WsGrand, "Z,ZZZ,ZZZ,ZZ9.99")
	// DISPLAY "NEW: " WS-NEW-COUNT " SHIPPED: " WS-SHIP-COUNT " CANCELLED: " WS-CANCEL-COUNT
	fmt.Printf("NEW: %s SHIPPED: %s CANCELLED: %s\n",
		formatIntPadded(WsNewCount, 2),
		formatIntPadded(WsShipCount, 2),
		formatIntPadded(WsCancelCount, 2))
	fmt.Printf("INVALID: %s BAD QTY: %s\n",
		formatIntPadded(WsInvalid, 2),
		formatIntPadded(WsBadQty, 2))
	fmt.Printf("GRAND TOTAL: %s\n", WsGrandEd)
}

func main() {
	MAIN_PARA()
}
